// Builds AttachSignedDocumentRequest for the draft with the same Work Order ID.
const out = [];
for (const item of $input.all()) {
  const res = item.json;
  if (res.stop_reason === 'refusal') throw new Error('Claude declined to read this document');
  const textBlock = (res.content || []).find((b) => b.type === 'text');
  if (!textBlock) throw new Error('No text in the extraction response');
  const f = JSON.parse(textBlock.text);
  if (!f.fullySigned) throw new Error(`${f.workOrderId}: not signed by all parties yet; not importing`);
  const sha = $('Fingerprint PDF (SHA-256)').item.json.pdfSha256;
  const file = $('New signed work order (Drive)').item.json;
  out.push({ json: {
    workOrderId: f.workOrderId,
    body: {
      method: 'google_esign',
      documentSha256: sha,
      documentUrl: file.webViewLink || null,
      signedAt: f.signers.map((s) => s.signedAt).filter(Boolean).sort().pop() || null,
      signers: f.signers.map((s) => ({ name: s.name, role: s.role, signedAt: s.signedAt || null })),
      extracted: {
        workOrderId: f.workOrderId, project: f.project, contractorName: f.contractorName,
        representativeName: f.representativeName, periodStart: f.periodStart, periodEnd: f.periodEnd,
        budgetUsd: f.budgetUsd, payee: f.payee || null, contractorGithub: f.contractorGithub || null,
        repos: f.repos && f.repos.length ? f.repos : null,
      },
    },
  } });
}
return out;

// Builds the Anthropic Messages API request (a Code node, because '}}' inside an n8n
// expression ends the expression and the nested JSON schema has many of them).
const schema = {
  "type": "object",
  "additionalProperties": false,
  "required": [
    "workOrderId",
    "title",
    "project",
    "contractorName",
    "contractorEmail",
    "representativeName",
    "representativeEmail",
    "effectiveDate",
    "periodStart",
    "periodEnd",
    "budgetUsd",
    "ipModel",
    "servicesAgreementDate",
    "signers",
    "fullySigned",
    "payee",
    "contractorGithub",
    "repos"
  ],
  "properties": {
    "workOrderId": {
      "type": "string",
      "description": "Work Order ID exactly as written in the header, e.g. SI-002"
    },
    "title": {
      "type": "string",
      "description": "Document title, e.g. 'MultiAgency Work Order | Contributor Role'"
    },
    "project": {
      "type": "string"
    },
    "contractorName": {
      "type": "string"
    },
    "contractorEmail": {
      "type": "string",
      "description": "Contractor email if present anywhere (signature block or audit trail), else empty string"
    },
    "representativeName": {
      "type": "string"
    },
    "representativeEmail": {
      "type": "string",
      "description": "Representative email if present, else empty string"
    },
    "effectiveDate": {
      "type": "string",
      "description": "YYYY-MM-DD"
    },
    "periodStart": {
      "type": "string",
      "description": "Work period start, YYYY-MM-DD"
    },
    "periodEnd": {
      "type": "string",
      "description": "Work period end, YYYY-MM-DD"
    },
    "budgetUsd": {
      "type": "string",
      "description": "Approved budget in USD as a plain decimal, e.g. '1000'"
    },
    "ipModel": {
      "type": "string",
      "enum": [
        "assignment",
        "license",
        "open_source",
        "other",
        ""
      ]
    },
    "servicesAgreementDate": {
      "type": "string",
      "description": "YYYY-MM-DD or empty string"
    },
    "payee": {
      "type": "string",
      "description": "Payout account (NEAR) from Schedule A, or empty string"
    },
    "contractorGithub": {
      "type": "string",
      "description": "Contractor GitHub account from Schedule A, or empty string"
    },
    "repos": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Repositories in scope from Schedule A (owner/name), or empty"
    },
    "signers": {
      "type": "array",
      "description": "Each signer from the signature block / audit trail",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "name",
          "role",
          "signedAt"
        ],
        "properties": {
          "name": {
            "type": "string"
          },
          "role": {
            "type": "string",
            "enum": [
              "contractor",
              "representative"
            ]
          },
          "signedAt": {
            "type": "string",
            "description": "ISO 8601 time from the audit trail, or empty string"
          }
        }
      }
    },
    "fullySigned": {
      "type": "boolean",
      "description": "True only if the audit trail says it was signed by all signers / completed"
    }
  }
};
return $input.all().map((item) => ({ json: { anthropicRequest: {
  model: 'claude-opus-5-5',
  max_tokens: 4000,
  fallbacks: 'default',
  output_config: { effort: 'low', format: { type: 'json_schema', schema } },
  system: 'You extract fields from a signed work order. Copy values exactly as written; convert dates to YYYY-MM-DD. Use an empty string when a field is absent. Never invent values.',
  messages: [{ role: 'user', content: 'Work order text:\n\n' + (item.json.text || '') }],
} } }));
